<script lang="ts">
  import type {Row} from '#lib/client/types.ts';
  import {reportMoney,reportNumber,reportQuantity} from '#lib/client/reports.ts';
  let {rows,fields,unit='',currency,caption,monetary=false}:{rows:Row[];fields:{key:string;label:string;color:string}[];unit?:string;currency?:string;caption:string;monetary?:boolean}=$props();
  const colors=['var(--chart-muted)','var(--forest)','var(--chart-secondary)'];
  const values=$derived(rows.flatMap(row=>fields.map(field=>reportNumber(row[field.key]))).filter((value):value is number=>value!==null));
  const maximum=$derived(Math.max(0,...values.map(value=>Math.abs(value))));
  const negatives=$derived(values.some(value=>value<0));
  function valueLabel(value:unknown,row:Row){return monetary||currency||row.currency?reportMoney(value,row.currency||currency):reportQuantity(value,unit);}
</script>
<div class="comparison"><p class="comparison-caption">{caption}</p><p class="field-help">{#if values.length}Gemeinsame Skala {negatives?'von −':''}{valueLabel(maximum,{})}{negatives?' bis +'+valueLabel(maximum,{}):' ab null'}. {negatives?'Null liegt in der Mitte.':''} Fehlende Grundlagen erhalten keinen Balken.{:else}Für diesen Vergleich liegen noch keine bestätigten Zahlen vor.{/if}</p><div class="comparison-legend">{#each fields as field,index}<span><i style={`background:${colors[index%colors.length]}`}></i>{field.label}</span>{/each}</div>{#each rows as row}<div class="comparison-group"><h4>{row.label}</h4>{#each fields as field,index}{@const value=reportNumber(row[field.key])}<div class="comparison-row"><span>{field.label}</span><div class:negative-axis={negatives} class="comparison-track" aria-hidden="true">{#if value!==null}<i style={`background:${colors[index%colors.length]};width:${maximum?Math.abs(value)/maximum*(negatives?50:100):0}%;left:${negatives?(value<0?50-(maximum?Math.abs(value)/maximum*50:0):50):0}%`}></i>{/if}</div><strong>{valueLabel(row[field.key],row)}</strong></div>{/each}</div>{/each}</div>
<style>.comparison{padding:24px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.comparison-caption{font-size:13px;font-weight:500;margin-bottom:6px}.comparison-legend{display:flex;gap:10px 22px;flex-wrap:wrap;margin:18px 0 23px;font-size:13px}.comparison-legend>span{display:flex;gap:7px;align-items:center}.comparison-legend i{width:9px;height:12px;border-radius:4px}.comparison-group+.comparison-group{margin-top:25px}.comparison-group h4{font-size:13px;font-weight:500;margin-bottom:12px}.comparison-row{display:grid;grid-template-columns:minmax(85px,150px) minmax(25px,1fr) minmax(115px,auto);gap:16px;align-items:center;font-size:11px;margin-top:10px}.comparison-row>strong{text-align:right;font-size:12px;font-weight:500;font-variant-numeric:tabular-nums}.comparison-track{position:relative;background:var(--wash);height:9px;border-radius:2px;overflow:hidden}.comparison-track>i{position:absolute;top:0;height:100%;border-radius:2px}.comparison-track.negative-axis:after{content:'';position:absolute;left:50%;top:0;bottom:0;border-left:1px solid var(--muted)}@media(max-width:760px){.comparison{padding:21px 20px}.comparison-caption{font-size:14px}.comparison-row{grid-template-columns:70px minmax(25px,1fr);gap:6px 12px;font-size:12px}.comparison-row>strong{grid-column:2;text-align:left;font-size:12px}.comparison-row>span{grid-row:span 2;align-self:start}.comparison-group h4{font-size:13px}.comparison-legend{font-size:12px}}</style>
